                  <span style={{width:22,height:22,borderRadius:7,display:"grid",placeItems:"center",background:"linear-gradient(135deg,#a78bfa,#7c3aed)",color:"#fff",fontSize:12,fontWeight:800,flexShrink:0}}>7</span>
