                  <div style={{fontSize:32,fontWeight:800,color:currentStreak>1?(streakType==="won"?"#22C55E":"#EF4444"):"#3a4a5e",lineHeight:1,letterSpacing:-1}}>{currentStreak>1?currentStreak:"—"}</div>
