                  <div>
                    <div style={{fontSize:13,fontWeight:700,color:"#E5E7EB"}}>Corbeille</div>
                    <div style={{fontSize:10,color:"#6B7280"}}>{deletedBets.length} paris supprimés récemment</div>
                  </div>
